20	/**
21	 * Map a raw location pathname to an app route. The exported bundle may be
22	 * opened straight from the filesystem, where the pathname is a real file path
23	 * such as ".../output/index.html" or ".../output/_404.html".
24	 */
25	function normalize(path: string) {
26	  if (!path) return "/";
27	  const qAt = path.indexOf("?");
28	  if (qAt !== -1) path = path.slice(0, qAt);
29	  if (path.endsWith("/_404.html")) return "/_404.html";
30	  if (path.endsWith("/index.html")) return "/";
31	  if (path.endsWith(".html")) return path.slice(path.lastIndexOf("/"));
32	  if (path.length > 1 && path.endsWith("/")) return path.slice(0, -1);
33	  return path;
34	}
35	
36	/** Separate an href into pathname + hash + query so in-page anchors and search survive routing. */
37	function splitHref(href: string) {
38	  const hashAt = href.indexOf("#");
39	  const hash = hashAt === -1 ? "" : href.slice(hashAt);
40	  const noHash = hashAt === -1 ? href : href.slice(0, hashAt);
41	  const qAt = noHash.indexOf("?");
42	  const query = qAt === -1 ? "" : noHash.slice(qAt);
43	  const pathname = qAt === -1 ? noHash : noHash.slice(0, qAt);
44	  return { pathname, hash, query };
45	}
46	
47	export function RouterProvider({ children }: { children: ReactNode }) {
48	  const [path, setPath] = useState(() => normalize(window.location.pathname));
49	
50	  useEffect(() => {
51	    const onPop = () => setPath(normalize(window.location.pathname));
52	    window.addEventListener("popstate", onPop);
53	    return () => window.removeEventListener("popstate", onPop);
54	  }, []);
55	
56	  const navigate = useCallback((to: string) => {
57	    const { pathname, hash, query } = splitHref(to);
58	    const raw = pathname || window.location.pathname;
59	    const target = normalize(raw);
60	    // Preserve the reference's trailing-slash URL in the address bar even
61	    // though route matching normalizes it away.
62	    const address = raw.startsWith("/") ? raw : target;
63	    const samePath = target === normalize(window.location.pathname);
64	
65	    if (samePath) {
66	      if (query) {
67	        try {
68	          window.history.replaceState({}, "", address + query + hash);
69	        } catch {
70	          /* opaque origin */
71	        }
72	      }
73	      if (hash) document.getElementById(hash.slice(1))?.scrollIntoView({ behavior: "smooth" });
74	      return;
75	    }
76	
77	    try {
78	      window.history.pushState({}, "", address + query + hash);
79	    } catch {
80	      // e.g. opaque file:// origins where the History API is restricted.
81	    }
82	    setPath(target);
83	    if (hash) {
84	      window.requestAnimationFrame(() => {
85	        document.getElementById(hash.slice(1))?.scrollIntoView({ behavior: "smooth" });
86	      });
87	    } else {
88	      window.scrollTo(0, 0);
89	    }
90	  }, []);
91	
92	  const value = useMemo(() => ({ path, navigate }), [path, navigate]);
93	  return <RouterContext.Provider value={value}>{children}</RouterContext.Provider>;
94	}
95	
96	export function useRouter() {
97	  return useContext(RouterContext);
98	}
99	
100	/** hrefs the browser can resolve on its own: mail, phone, and bare anchors. */
101	function isBrowserHandled(href: string) {
102	  return (
103	    href.startsWith("#") ||
104	    href.startsWith("tel:") ||
105	    href.startsWith("mailto:") ||
106	    href.startsWith("javascript:")
107	  );
108	}
109	
110	type LinkProps = AnchorHTMLAttributes<HTMLAnchorElement> & {
111	  /** Destination path such as "/about/" or "/schools-colleges/". */
112	  to: string;
113	};
114	
115	/**
116	 * Client-side anchor. Root-relative destinations route through the in-app
117	 * router; protocol links and bare anchors fall through to the browser.
118	 */
119	export function Link({ to, children, onClick, ...rest }: LinkProps) {
120	  const { navigate } = useRouter();
121	
122	  if (isBrowserHandled(to)) {
123	    return (
124	      <a href={to} {...rest} onClick={onClick}>
125	        {children}
126	      </a>
127	    );
128	  }
129	
130	  const internal = to.startsWith("/");
131	  const href = internal ? to : "#";
132	
133	  const handleClick = (event: MouseEvent<HTMLAnchorElement>) => {
134	    onClick?.(event);
135	    if (!internal) {
136	      event.preventDefault();
137	      return;
138	    }
139	    if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey || event.button !== 0) {
140	      return;
141	    }
142	    event.preventDefault();
143	    navigate(to);
144	  };
145	
146	  return (
147	    <a href={href} {...rest} onClick={handleClick}>
148	      {children}
149	    </a>
150	  );
151	}
152

